// 02 - Engine: Telegram messages -> profile state machine + commands.
// Personal bot: the first chat that sends /start becomes the owner; all other chats are ignored.
const upd = $input.first().json;
const msg = upd.message;
if (!msg || !msg.chat) return [];
// media: scholarship poster (photo / image file) or voice note
let media = null;
if (Array.isArray(msg.photo) && msg.photo.length) media = { kind: 'image', file_id: msg.photo[msg.photo.length - 1].file_id, mime: 'image/jpeg' };
else if (msg.document && /^image\//.test(msg.document.mime_type || '')) media = { kind: 'image', file_id: msg.document.file_id, mime: msg.document.mime_type };
else if (msg.voice) media = { kind: 'voice', file_id: msg.voice.file_id, mime: msg.voice.mime_type || 'audio/ogg' };
else if (msg.audio) media = { kind: 'voice', file_id: msg.audio.file_id, mime: msg.audio.mime_type || 'audio/mpeg' };
const rawText = typeof msg.text === 'string' ? msg.text : typeof msg.caption === 'string' ? msg.caption : '';
if (!media && !rawText) return [];
const chatId = String(msg.chat.id);
const text = rawText.trim().slice(0, 500);
const updateId = Number(upd.update_id || 0);
const cmd = !media && text.startsWith('/') ? text.split(/[\s@]/)[0].toLowerCase() : '';
const arg = cmd ? text.slice(text.indexOf(cmd) + cmd.length).replace(/^@\S+/, '').trim() : '';

const store = $getWorkflowStaticData('global');
if (store.owner && store.owner !== chatId) return [];
if (store.last_update_id && updateId && updateId <= store.last_update_id) return []; // duplicate delivery
if (updateId) store.last_update_id = updateId;

const out = [];
const reply = (t) => out.push({ json: { route_index: 0, chat_id: chatId, text: t } });
const search = (extra) => {
  store.pending = { chat_id: chatId, mode: 'manual', extra: extra || '' };
  out.push({ json: { route_index: 1, chat_id: chatId } });
};
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const SKIP = new Set(['-', 'تخطي', 'skip', 'لا', 'no']);


const GUIDE = [
  '📘 <b>دليل استخدام رادار المنح</b>',
  '',
  '<b>1️⃣ التسجيل (مرة واحدة)</b>',
  'أجب عن 7 أسئلة: الجنسية، المرحلة، التخصص، التخصص السابق، سنة التقديم، مكان دراستك، والدول.',
  '• اكتب «-» لتخطي الأسئلة الاختيارية.',
  '• في سؤال الدول اكتب «الكل» للبحث في كل العالم.',
  '',
  '<b>2️⃣ البحث</b>',
  '• بعد التسجيل أبحث لك فوراً عن المنح المناسبة، وفي تخصصك والتخصصات القريبة منه.',
  '• /search بحث جديد في أي وقت.',
  '• أو اكتب طلبك مباشرة، مثال: «منح بتمويل كامل في كندا».',
  '',
  '<b>🤖 المساعد الذكي</b>',
  '• اكتب أي رسالة بشكل طبيعي: أفهم وحدي إن كنت تبحث عن منح أو تسأل سؤالاً.',
  '• /ask سؤالك مباشرة للمساعد، مثال: /ask أي منحة محفوظة أبدأ بها؟',
  '• المساعد يعرف بياناتك ومنحك المحفوظة ومستنداتك، ويتذكر المحادثة، ويستطيع فتح صفحات المنح الرسمية ليجيبك منها.',
  '',
  '<b>📸 🎙️ صور ورسائل صوتية</b>',
  '• أرسل صورة إعلان منحة (بوستر أو لقطة شاشة) فأقرأها وأحوّلها لبطاقة كاملة مع نسبة تطابقها معك.',
  '• أرسل رسالة صوتية بدل الكتابة، وأفهمها كأنك كتبتها.',
  '⏳ البحث يأخذ حتى دقيقتين.',
  '',
  '<b>3️⃣ بطاقة المنحة</b>',
  'كل منحة تصلك فيها: النوع والتمويل، نسبة التطابق وسببها، ماذا تغطي، شرط القبول الجامعي وروابطه، الجامعات، الموعد النهائي، المستندات، ورابط التقديم.',
  '⚠️ تعني أن المعلومة غير متوفرة.',
  '',
  '<b>4️⃣ حفظ المنح ومتابعتها</b>',
  '• /save 12 احفظ المنحة رقم 12 (الرقم أسفل كل بطاقة) ويُضاف موعدها لتقويم Google · /unsave 12 إلغاء.',
  '• /stats عدد المنح، المحفوظة، وأقرب موعد نهائي، مع رسوم بيانية.',
  '• ✅ بجانب الرابط = تم التحقق أنه يعمل · ❌ = الرابط لا يعمل.',
  '• ✔️ بجانب الموعد = وجدته مكتوباً في صفحة المنحة · ⚠️ غير مؤكد = تحقق منه، وصححه بـ /deadline 12 2026-10-20',
  '• /docs قائمة موحّدة بمستندات المنح المحفوظة.',
  '• /done 1 3 علّم ما جهّزته · /undo 1 تراجع.',
  '',
  '<b>5️⃣ التقرير اليومي والتذكير</b>',
  `• كل صباح الساعة ${store.profile && Number.isInteger(store.profile.digest_hour) ? store.profile.digest_hour : 8}:00 تصلك المنح <b>الجديدة</b> فقط على Telegram وعلى الإيميل.`,
  '• يصلك تذكير بالمنح المحفوظة قبل موعدها بـ 30 و14 و7 و3 و1 يوم ويوم الموعد.',
  '• /time 7 لتغيير الساعة · /daily off لإيقاف التقرير · /daily on لتشغيله.',
  '',
  '<b>6️⃣ بياناتك</b>',
  '• /profile عرض · /edit تعديل · /reset_seen إعادة عرض كل المنح · /delete حذف كل شيء.',
  '• /guide هذا الدليل · /help قائمة الأوامر المختصرة.',
  '',
  '🔎 النتائج من بحث آلي على الويب: تأكد دائماً من الشروط والروابط في الموقع الرسمي قبل التقديم.',
].join('\n');

const STEPS = ['nat', 'degree', 'field', 'prev', 'intake', 'study', 'dest'];
const ASK = {
  nat: '1/7 — ما جنسيتك؟ (مثال: فلسطينية)',
  degree: '2/7 — ما المرحلة التي تريد التقديم عليها؟\nبكالوريوس / ماجستير / دكتوراه',
  field: '3/7 — ما التخصص الذي تريد دراسته؟ (اكتبه بحرية)\nسأبحث أيضاً في التخصصات القريبة منه.',
  prev: '4/7 — ما تخصصك السابق؟ (أو «-» للتخطي)',
  intake: '5/7 — لأي سنة دراسية تريد التقديم؟ (مثال: 2027، أو «-» للتخطي)',
  study: '6/7 — أين درست/تدرس الآن؟ الجامعة والدولة (أو «-» للتخطي)',
  dest: '7/7 — أين تريد الدراسة؟\n🌍 اكتب «الكل» للبحث في كل دول العالم\nأو اكتب دولاً محددة مفصولة بفاصلة (مثال: ألمانيا، إيطاليا، كندا)',
};
const DEGREE = (s) => {
  const n = s.toLowerCase();
  if (/بكا?لو?ري?و?س|بكلوريوس|ليسانس|جامعي اول|bachelor|\bba\b|\bbsc\b|undergrad/.test(n)) return 'بكالوريوس';
  if (/ماجستير|ماجيستير|ماستر|ماسترز|master|\bma\b|\bmsc\b|\bmba\b/.test(n)) return 'ماجستير';
  if (/دكتورا[هةء]?|دكتوره|phd|ph\.d|doctor/.test(n)) return 'دكتوراه';
  return null;
};

const showProfile = (p) => [
  '👤 <b>بياناتك</b>',
  `الجنسية: ${esc(p.nat) || '—'}`,
  `المرحلة: ${esc(p.degree) || '—'}`,
  `التخصص: ${esc(p.field) || '—'}`,
  `التخصص السابق: ${esc(p.prev) || '—'}`,
  `سنة التقديم: ${esc(p.intake) || '—'}`,
  `مكان الدراسة: ${esc(p.study) || '—'}`,
  `الدول: ${esc(p.dest) || '—'}`,
  `التقرير اليومي: ${p.daily === false ? 'متوقف' : 'الساعة ' + (p.digest_hour ?? 8) + ':00 (غزة)'}`,
].join('\n');

if (cmd === '/start' || cmd === '/edit') {
  store.owner = store.owner || chatId;
  const old = store.profile || {};
  store.profile = { step: 'nat', daily: old.daily, digest_hour: old.digest_hour };
  if (cmd === '/start') {
    reply('👋 أهلاً بك في <b>رادار المنح</b>!\nأحفظ بياناتك وأبحث لك عن المنح المناسبة، وأرسل لك الجديد كل صباح.\nاقرأ الدليل التالي ثم أجب عن الأسئلة 👇');
    reply(GUIDE);
    reply('لنبدأ التسجيل ✍️\n' + ASK.nat);
  } else {
    reply('✏️ لنعدّل بياناتك.\n' + ASK.nat);
  }
  return out;
}
if (cmd === '/guide') {
  if (!store.owner) { reply(GUIDE + '\n\nأرسل /start للبدء.'); return out; }
  reply(GUIDE);
  if (store.profile && store.profile.step !== 'done') reply('لنكمل من حيث توقفنا:\n' + ASK[store.profile.step]);
  return out;
}
const p = store.profile;
if (!p) { reply('أرسل /start لإدخال بياناتك أولاً، أو /guide لقراءة الدليل.'); return out; }
if (media && p.step !== 'done') { reply('أكمل الأسئلة أولاً، ثم أرسل الصور أو الرسائل الصوتية.\n' + ASK[p.step]); return out; }

if (cmd === '/delete') { for (const k of ['profile', 'seen', 'items', 'key_to_id', 'saved', 'docs_ready', 'docs_last', 'next_id', 'cal_events', 'link_status', 'reminded']) delete store[k]; reply('🗑️ تم حذف بياناتك.'); return out; }
if (cmd === '/help') {
  reply('📘 الدليل الكامل: /guide\n📸 أرسل صورة إعلان منحة · 🎙️ أو رسالة صوتية\n\nالأوامر:\n/ask سؤالك للمساعد الذكي\n/profile بياناتك\n/edit تعديل\n/search بحث الآن\n/save 12 حفظ منحة · /unsave 12 إلغاء الحفظ\n/deadline 12 2026-10-20 تصحيح موعد منحة\n/stats إحصائياتك\n/docs قائمة المستندات · /done 3 جهّزته · /undo 3 تراجع\n/daily on|off التقرير اليومي\n/time 8 ساعة التقرير (0-23)\n/reset_seen إعادة عرض كل المنح\n/delete حذف\nأو اكتب أي طلب مباشرة، مثال: «منح ماجستير ذكاء اصطناعي بتمويل كامل».');
  return out;
}


// ---------- answer validation for the 7 onboarding questions ----------
const toLatinDigits = (s) => String(s).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const normAr = (s) => String(s).toLowerCase().replace(/[إأآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').replace(/ـ/g, '').replace(/\bال/g, '').trim();
const PLACE_STEMS = ['فلسطين','غزه','اردن','مصر','سوري','لبنان','عراق','سعودي','يمن','ليبي','تونس','جزائر','مغرب','سودان','امارات','اماراتي','كويت','قطر','بحرين','عمان','موريتان','صومال','جيبوت','قمر','ترك','ايران','افغان','باكستان','هند','بنغلاد','اندونيس','ماليزي','نيجير','اثيوب','كيني','غان','امريك','ولايات متحده','بريطان','انجلتر','انكلتر','مملكه متحده','سكتلند','الماني','المان','فرنس','ايطال','اسبان','برتغال','روس','صين','يابان','كوري','كند','استرال','نيوزيلند','هولند','بلجيك','سويد','نرويج','دنمارك','فنلند','نمسا','سويسر','ايرلند','بولند','تشيك','مجر','هنغار','روماني','يونان','قبرص','مالط','سنغافور','تايوان','هونغ','بروناي','اوروب','اسيا','افريق','جنوب افريق','برازيل','مكسيك','ارجنتين','تشيل','استون','لاتفي','ليتوان','سلوفاك','سلوفين','كروات','صرب','بلغار','اوكران','جورج','اذربيج','كازاخ','اوزبك','تايلند','فيتنام','فلبين','سريلانك','نيبال'];
const PLACE_EN = /(palestin|gaza|jordan|egypt|syria|leban|iraq|saudi|yemen|liby|tunis|alger|morocc|sudan|emirat|uae|kuwait|qatar|bahrain|oman|mauritan|somal|djibout|comor|turk|iran|afghan|pakistan|india|bangl|indones|malays|niger|ethiop|keny|ghan|americ|usa|\bus\b|united states|brit|\buk\b|england|scotl|united kingdom|german|france|french|ital|spain|spanish|portug|russia|chin|japan|korea|canad|austral|zealand|netherland|dutch|holland|belgi|swed|norw|denmark|danish|finland|finnish|austria|switzerland|swiss|ireland|irish|poland|polish|czech|hungar|romania|greece|greek|cyprus|malta|singapore|taiwan|hong kong|brunei|europe|asia|africa|brazil|mexic|argentin|chile|estonia|latvia|lithuania|slovak|sloven|croatia|serbia|bulgaria|ukrain|georgia|azerbaij|kazakh|uzbek|thai|vietnam|philippin|sri lanka|nepal)/i;
const knownPlace = (s) => PLACE_EN.test(s) || PLACE_STEMS.some((st) => normAr(s).includes(st));
const hasLetters = (s) => /[A-Za-z؀-ۿ]/.test(s);
const badText = (s) => /https?:\/\/|www\.|@/.test(s) || !hasLetters(s);
const YES = /^(تأكيد|تاكيد|نعم|اي|أي|ايوه|أيوه|صح|yes|ok|okay|confirm)$/i;
const thisYear = DateTime.now().setZone('Asia/Gaza').year;

// returns { ok, val } or { ok:false, msg } or { confirm, val, msg } (accepted after the user replies «تأكيد»)
const validate = (key, raw) => {
  const t = raw.trim();
  const skip = SKIP.has(t.toLowerCase());
  const words = t.split(/\s+/).filter(Boolean).length;
  switch (key) {
    case 'nat': {
      if (skip) return { ok: false, msg: '⚠️ الجنسية مطلوبة ولا يمكن تخطيها.' };
      if (badText(t) || /\d/.test(t) || t.length < 3 || t.length > 40 || words > 4) return { ok: false, msg: '⚠️ هذه لا تبدو جنسية. اكتبها بكلمة أو كلمتين، مثال: فلسطيني، أردنية، Egyptian.' };
      if (!knownPlace(t)) return { confirm: true, val: t, msg: `⚠️ لم أتعرف على الجنسية «${esc(t)}».\nاكتبها مرة أخرى بشكل أوضح (مثال: فلسطيني)، أو أرسل «تأكيد» إن كانت صحيحة.` };
      return { ok: true, val: t };
    }
    case 'degree': {
      const d = DEGREE(t);
      return d ? { ok: true, val: d } : { ok: false, msg: '⚠️ اكتب واحدة فقط: بكالوريوس أو ماجستير أو دكتوراه.' };
    }
    case 'field':
    case 'prev': {
      if (skip) return key === 'prev' ? { ok: true, val: null } : { ok: false, msg: '⚠️ التخصص مطلوب ولا يمكن تخطيه.' };
      if (badText(t) || /^\d+$/.test(t) || t.length < 2 || t.length > 80 || words > 10) return { ok: false, msg: '⚠️ اكتب اسم التخصص فقط (حتى 10 كلمات)، مثال: علم البيانات، هندسة مدنية، Computer Science.' };
      if (/^(مرحبا|اهلا|أهلا|السلام عليكم|hi|hello|test|تجربه|تجربة|لا اعرف|مش عارف|\?|؟)$/i.test(t)) return { ok: false, msg: '⚠️ هذا ليس تخصصاً. اكتب اسم التخصص، مثال: إدارة أعمال.' };
      return { ok: true, val: t };
    }
    case 'intake': {
      if (skip) return { ok: true, val: null };
      const years = (toLatinDigits(t).match(/\b(19|20)\d{2}\b/g) || []).map(Number);
      if (!years.length) return { ok: false, msg: `⚠️ اكتب سنة من 4 أرقام، مثال: ${thisYear + 1}، أو «-» للتخطي.` };
      const y = years[0];
      if (y < thisYear) return { ok: false, msg: `⚠️ السنة ${y} مضت. اكتب سنة من ${thisYear} فما بعد، أو «-» للتخطي.` };
      if (y > thisYear + 5) return { ok: false, msg: `⚠️ السنة ${y} بعيدة جداً. اكتب سنة بين ${thisYear} و${thisYear + 5}.` };
      return { ok: true, val: String(y) };
    }
    case 'study': {
      if (skip) return { ok: true, val: null };
      if (badText(t) || t.length < 3 || t.length > 100) return { ok: false, msg: '⚠️ اكتب اسم الجامعة والدولة، مثال: الجامعة الإسلامية، غزة. أو «-» للتخطي.' };
      return { ok: true, val: t };
    }
    case 'dest': {
      if (skip || /^(الكل|كل الدول|كل العالم|اي دولة|أي دولة|اي|أي|all|any|anywhere|worldwide)$/i.test(t)) return { ok: true, val: 'كل الدول' };
      if (badText(t) || t.length > 200) return { ok: false, msg: '⚠️ اكتب أسماء دول مفصولة بفاصلة، مثال: ألمانيا، كندا. أو «الكل».' };
      const parts = t.split(/[,،\n]+|\s+و(?=\S)|\s+and\s+/i).map((x) => x.trim()).filter(Boolean);
      if (parts.length > 15) return { ok: false, msg: '⚠️ اختر حتى 15 دولة، أو اكتب «الكل».' };
      const unknown = parts.filter((x) => !knownPlace(x));
      const clean = parts.join('، ');
      if (unknown.length) return { confirm: true, val: clean, msg: `⚠️ لم أتعرف على: «${esc(unknown.join('، '))}».\nصحّح الأسماء وأرسلها من جديد، أو أرسل «تأكيد» إن كانت صحيحة.` };
      return { ok: true, val: clean };
    }
  }
  return { ok: true, val: t };
};

if (p.step !== 'done') {
  if (cmd) { reply('أكمل الأسئلة أولاً.\n' + ASK[p.step]); return out; }
  const key = p.step;
  let res;
  if (p.confirm && p.confirm.key === key && YES.test(text.trim())) res = { ok: true, val: p.confirm.val };
  else res = validate(key, text);
  if (res.confirm) { p.confirm = { key, val: res.val }; reply(res.msg); return out; }
  if (!res.ok) { reply(res.msg + '\n\n' + ASK[key]); return out; }
  delete p.confirm;
  p[key] = res.val;
  const next = STEPS[STEPS.indexOf(key) + 1];
  if (next) { p.step = next; reply(ASK[next]); return out; }
  p.step = 'done';
  reply('✅ تم حفظ بياناتك. جارٍ البحث عن المنح المناسبة…\n(سيصلك تقرير يومي بالمنح الجديدة. /help للأوامر)');
  search('');
  return out;
}

// profile complete

// ---------- context for the AI assistant (/ask and free-text questions) ----------
const buildSystem = () => {
  const pr = store.profile || {};
  const items = store.items || {};
  const saved = (store.saved || []).filter((id) => items[id]);
  const ready = store.docs_ready || {};
  const dk = (d) => String(d).toLowerCase().replace(/[\s\-_.،,:()]+/g, ' ').trim();
  const line = (id) => {
    const it = items[id];
    const bits = [`#${id} ${it.name}`, it.country, it.type, it.fund, it.deadline ? 'deadline ' + it.deadline : 'deadline unknown',
      it.adm ? 'admission: ' + it.adm : null, it.cover ? 'covers: ' + it.cover : null,
      it.score != null ? 'match ' + it.score + '%' : null, it.apply_link ? 'link ' + it.apply_link : null];
    const docs = (it.docs || []).map((d) => (ready[dk(d)] ? '[ready] ' : '[missing] ') + d).join('; ');
    return '- ' + bits.filter(Boolean).join(' | ') + (docs ? ' | docs: ' + docs : '');
  };
  const recent = Object.keys(items).map(Number).filter((id) => !saved.includes(id)).sort((a, b) => b - a).slice(0, 15);
  const today = DateTime.now().setZone('Asia/Gaza').toISODate();
  return [
    'You are "رادار المنح" (Scholarship Radar), a friendly personal scholarship advisor inside a Telegram bot.',
    `Today: ${today} (Asia/Gaza).`,
    'Answer in Arabic (unless the user writes in English), clearly and briefly (max ~180 words). Use short paragraphs or "•" bullets. No tables. You may use **bold**.',
    'Use the user profile and scholarship lists below. Refer to scholarships by their #number.',
