const buildDocs = () => {
  const map = new Map();
  for (const id of store.saved) {
    const it = store.items[id];
    if (!it) continue;
    for (const d of it.docs || []) {
      const k = docKey(d);
      if (!k) continue;
      if (!map.has(k)) map.set(k, { name: d, ids: [] });
      if (!map.get(k).ids.includes(id)) map.get(k).ids.push(id);
    }
  }
  return [...map.entries()].sort((a, b) => b[1].ids.length - a[1].ids.length || a[0].localeCompare(b[0]));
