// 04 - Daily Job: runs every hour. At the user's chosen hour (once per day) it:
//  1) sends deadline reminders for saved scholarships (30, 14, 7, 3, 1 days before, and on the day)
//  2) starts the daily search (if /daily is on).
const REMIND_DAYS = [30, 14, 7, 3, 1, 0];
const store = $getWorkflowStaticData('global');
const p = store.profile;
if (!store.owner || !p || p.step !== 'done') return [];
const now = DateTime.now().setZone('Asia/Gaza');
const hour = Number.isInteger(p.digest_hour) ? p.digest_hour : 8;
const today = now.toISODate();
if (now.hour < hour) return [];
const out = [];
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---------- 1) deadline reminders ----------
if (store.last_reminder_date !== today) {
  store.last_reminder_date = today;
  store.reminded = store.reminded || {};
  const items = store.items || {};
  const ready = store.docs_ready || {};
  const docKey = (d) => String(d).toLowerCase().replace(/[\s\-_.،,:()]+/g, ' ').trim();
  const start = now.startOf('day');
  const due = [];
  for (const id of store.saved || []) {
    const it = items[id];
    if (!it || !it.deadline) continue;
    const left = Math.round(DateTime.fromISO(it.deadline, { zone: 'Asia/Gaza' }).diff(start, 'days').days);
    if (left < 0) continue;
    const sent = store.reminded[id] || [];
    const hit = REMIND_DAYS.filter((t) => left <= t && !sent.includes(t));
    if (!hit.length) continue;
    // mark every threshold already reached, so a late save does not trigger several reminders
    store.reminded[id] = [...new Set(sent.concat(REMIND_DAYS.filter((t) => left <= t)))];
    const missing = (it.docs || []).filter((d) => !ready[docKey(d)]);
    due.push({ id, it, left, missing });
  }
  // forget reminder state of scholarships that are no longer saved
  for (const id of Object.keys(store.reminded)) if (!(store.saved || []).includes(Number(id))) delete store.reminded[id];

  if (due.length) {
    due.sort((a, b) => a.left - b.left);
    const lines = ['⏰ <b>تذكير بالمواعيد النهائية</b>'];
    for (const { id, it, left, missing } of due) {
      lines.push('');
      lines.push(`${left <= 3 ? '🔴' : left <= 7 ? '🟠' : '🟡'} <b>${esc(it.name)}</b> (#${id})`);
      lines.push(`📅 ${it.deadline} — ${left === 0 ? '<b>اليوم آخر يوم!</b>' : left === 1 ? 'غداً آخر يوم' : 'باقي ' + left + ' يوم'}${it.deadline_ok === false ? ` ⚠️ غير مؤكد (صححه: /deadline ${id} YYYY-MM-DD)` : ''}`);
      if (it.docs && it.docs.length) {
        lines.push(missing.length ? `📄 متبقٍ ${missing.length} مستند: ${esc(missing.join('، '))}` : '📄 كل المستندات جاهزة ✅');
      }
      if (it.apply_link) lines.push(`🔗 <a href="${esc(it.apply_link)}">رابط التقديم</a>`);
    }
    out.push({ json: { route_index: 0, chat_id: store.owner, text: lines.join('\n').slice(0, 4000) } });
  }
}

